'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=o=>h(JSON.stringify(o,null,2));
const badge=s=>`<span class="badge ${h(s)}">${h(s)}</span>`;
const btn=(text,action,cls='',id='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${h(id)}">${text}</button>`;
const options=(items,id)=>items.map(x=>`<option value="${h(x.id)}" ${x.id===id?'selected':''}>${h(x.name||x.id.slice(0,12))}</option>`).join('');
const pages=[['dashboard','◫','Dashboard'],['chat','✧','QA Copilot'],['connections','⊞','Agent connections'],['explorer','◇','Agent explorer'],['suites','▤','Suite builder'],['execution','▷','Execution center'],['results','▥','Results explorer'],['coverage','◉','Coverage'],['regression','⇄','Regression'],['reports','↗','Reports'],['provider','⚙','AI activation']];
let state={page:location.hash.slice(1)||'dashboard',token:sessionStorage.getItem('agentqa-token')||'',agents:[],suites:[],runs:[],plans:[],agentId:localStorage.getItem('agentqa-agent')||'warehouse-demo',suiteId:'',runId:'',plan:null,executionCapabilities:null,generationJobs:[],selected:new Set(),chatSession:null,chatMessages:[],status:{}};
let poll=null;
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:{'Authorization':'Bearer '+state.token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok){let d;try{d=await r.json()}catch{d={detail:r.statusText}}throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));}return r.json();}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500);}
const agent=()=>state.agents.find(a=>a.id===state.agentId)||state.agents[0];
const suites=()=>state.suites.filter(s=>s.agent_id===agent()?.id);
const runs=()=>state.runs.filter(r=>r.agent_id===agent()?.id);
const suite=()=>suites().find(s=>s.id===state.suiteId)||suites()[0];
const run=()=>runs().find(r=>r.id===state.runId)||runs()[0];
function title(name,description,action=''){return `<div class="page-title"><div><div class="eyebrow">Your quality workspace</div><h1>${name}</h1><div class="muted">${description}</div></div><div class="actions">${action}</div></div>`;}
function empty(text,detail=''){return `<div class="empty"><strong>${text}</strong>${detail}</div>`;}
function jsonEditor(name,obj,save){$('#editor-content').innerHTML=`<h2>${h(name)}</h2><p class="sub">Edit the typed JSON contract. Changes invalidate existing execution approvals.</p><textarea id="json-editor" spellcheck="false">${pretty(obj)}</textarea><div class="actions">${btn('Save changes','save-json','primary')}</div>`;$('#editor').showModal();state.editorSave=save;}
async function refresh(){[state.agents,state.suites,state.runs,state.plans,state.status,state.generationJobs]=await Promise.all([api('/agents'),api('/suites'),api('/runs'),api('/plans'),api('/status'),api('/draft-requests')]);if(!state.agents.some(a=>a.id===state.agentId))state.agentId=state.agents[0]?.id;}
function login(){clearInterval(poll);$('#app').innerHTML=`<main class="login"><form id="login" class="card"><div class="logo">AQ</div><div class="eyebrow">Local evaluation workspace</div><h1>AgentQA Copilot</h1><p class="muted">Connect. Understand. Test with confidence.</p><label for="token" class="sub">Administrator token</label><input id="token" type="password" required autocomplete="current-password" placeholder="Paste your local access token"><button class="primary wide">Open workspace →</button><p class="sub section-space">Create a token with <code>scripts/create_admin.py</code>. It stays in this browser session.</p></form></main>`;$('#login').onsubmit=async e=>{e.preventDefault();state.token=$('#token').value;try{await refresh();sessionStorage.setItem('agentqa-token',state.token);await render();startPolling()}catch(err){toast(err.message)}};}
async function render(){if(!state.token)return login();const a=agent();state.executionCapabilities=a?await api('/agents/'+a.id+'/execution-capabilities'):null;$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="logo">AQ</div><div>AgentQA<small>COPILOT WORKSPACE</small></div></div><div class="nav-label">WORKSPACE</div><nav>${pages.map(([id,icon,label])=>`<button class="nav ${state.page===id?'active':''}" data-page="${id}"><span>${icon}</span>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div><span class="dot"></span>Local platform</div><p>Execution is approval-gated.<br>Evidence before assumptions.</p>${btn('Sign out','logout','tiny')}</div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span> / </span> ${h(pages.find(p=>p[0]===state.page)?.[2]||'Dashboard')}</div><div class="top-right"><select id="global-agent" aria-label="Selected agent">${options(state.agents,a?.id)}</select><span class="badge">LOCAL</span><div class="avatar" title="Local administrator">QA</div></div></header><section class="content" id="view"></section></main></div>`;if(!a){$('#view').innerHTML=empty('No agents connected');return}await renderPage();}
async function renderPage(){const view=$('#view');switch(state.page){case 'dashboard':view.innerHTML=dashboard();break;case 'chat':await chatPage();break;case 'provider':await providerPage();break;case 'connections':view.innerHTML=connections();break;case 'explorer':view.innerHTML=explorer();break;case 'suites':view.innerHTML=suitePage();break;case 'execution':view.innerHTML=execution();break;case 'results':view.innerHTML=results();break;case 'coverage':await coveragePage();break;case 'regression':view.innerHTML=regressionPage();break;case 'reports':view.innerHTML=reportsPage();break;default:state.page='dashboard';view.innerHTML=dashboard();}bindForms();}
function dashboard(){const rr=runs(),ss=suites(),results=rr.flatMap(r=>r.results),pass=results.filter(r=>r.verdict==='PASS').length,fail=results.filter(r=>r.verdict==='FAIL'||r.verdict==='ERROR').length,cost=rr.reduce((n,r)=>n+r.reserved_cost,0);return title('Quality, in focus.','A clear view of your agents and the evidence behind every result.',btn('Open Copilot','go-chat','primary'))+`<div class="banner"><div class="actions"><span class="banner-icon">✧</span><div><h3>Build confidence before the next release</h3><p>Explore capabilities, design meaningful tests, and review exactly what will run.</p></div></div>${btn('Build a test suite →','go-suites')}</div><div class="grid stats">${[['Connected agents',state.agents.length,'Independent adapters'],['Test cases',ss.reduce((n,s)=>n+s.cases.length,0),'Across selected agent suites'],['Evaluated pass rate',results.length?Math.round(pass/results.length*100)+'%':'—',results.length+' evaluated cases · all modes'],['Execution reservations','$'+cost.toFixed(2),'Estimates, not provider bills']].map(([label,n,sub])=>`<div class="card stat"><div class="stat-label">${label}</div><div class="stat-number">${n}</div><div class="sub">${sub}</div></div>`).join('')}</div><div class="grid two-col"><div class="card"><div class="card-head"><h2>Recent test runs</h2>${btn('View all →','go-results','tiny')}</div>${runTable(rr.slice(0,5))}</div><div class="card"><div class="card-head"><h2>Connected agents</h2><span class="sub">${state.agents.length} targets</span></div>${state.agents.map(a=>`<div class="agent-row"><div class="agent-icon">◇</div><div class="grow"><strong class="sub">${h(a.name)}</strong><div class="tiny muted">${h(a.adapter)} · ${h(a.environment)}</div></div>${badge(a.adapter==='source'?'source only':a.connection_status==='unverified'?'unverified':'ready')}</div>`).join('')}</div></div><div class="grid two-col section-space"><div class="card card-pad"><div class="split"><h2>Evaluation history</h2><span class="sub">Case outcomes per run</span></div>${rr.length?`<div class="timeline">${rr.slice(0,12).reverse().map((r,i)=>`<div data-height="${Math.max(4,r.results.filter(x=>x.verdict==='PASS').length/Math.max(r.results.length,1)*100)}" title="${h(r.id)}"><span>${i+1}</span></div>`).join('')}</div><div class="chart-legend"><span>■ Pass fraction</span><span>Includes static and simulated evaluations</span></div>`:empty('Your first run starts here','Review a suite, choose a mode, then inspect the evidence.')}</div><div class="card card-pad"><h2>Attention needed</h2><div class="kpi-row"><div><strong>${fail}</strong><span class="sub">Failures & errors</span></div><div><strong>${results.filter(r=>r.verdict==='INCONCLUSIVE').length}</strong><span class="sub">Evidence gaps</span></div></div><p class="sub">Company / HR live execution remains unapproved. Source discovery does not verify runtime authorization.</p>${btn('Review execution policy →','go-execution','tiny')}</div></div>`;}
function runTable(rr){return rr.length?`<div class="table-scroll"><table><thead><tr><th>Run</th><th>Mode</th><th>Results</th><th>Status</th><th></th></tr></thead><tbody>${rr.map(r=>`<tr><td><strong>${h(r.id.slice(0,8))}</strong><div class="tiny muted">${new Date(r.started_at).toLocaleString()}</div></td><td>${h(r.mode)}</td><td>${r.results.length} cases<div class="tiny muted">${r.results.filter(x=>x.verdict==='PASS').length} passed</div></td><td>${badge(r.status)}</td><td>${btn('Inspect','inspect-run','tiny',r.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('No runs yet','Static and mock modes are available without target execution.');}
function connections(){return title('Agent connections','Bring any observable agent into one QA workspace.',btn('+ Connect agent','add-agent','primary'))+`<div class="grid mini-grid">${state.agents.map(a=>`<article class="card connection-card"><div class="split"><div class="agent-icon">◇</div>${badge(a.environment)}</div><h2>${h(a.name)}</h2><p class="sub">${h(a.endpoint||'Local '+a.adapter+' integration')}</p><div class="pill-line">${badge(a.adapter)}${badge(a.isolation_verified?'isolation verified':'isolation unverified')}</div><p class="sub">${h(a.connection_status)}</p><div class="actions">${btn('Discover metadata','discover','',a.id)}${btn('Explore','select-explore','',a.id)}${['rest','langgraph'].includes(a.adapter)?btn('Verify isolation','verify-isolation','',a.id):''}</div><p class="tiny muted">Last discovery: ${h(a.last_discovery||'not yet')}</p></article>`).join('')}</div><div class="card card-pad section-space"><h2>LangSmith historical traces</h2><p class="sub">Import existing runs for offline evaluation. This never invokes the target agent.</p><form id="trace-import" class="toolbar"><div class="field"><label>Project name</label><input name="project" required placeholder="Existing LangSmith project"></div><div class="field"><label>Run limit</label><input name="limit" type="number" value="20" min="1" max="100"></div><button>Import historical runs</button>${btn('List projects','smith-projects')}</form><pre id="smith-output">${state.status.langsmith_configured?'LangSmith credentials configured server-side.':'LANGSMITH_API_KEY is not configured.'}</pre></div>`;}
function executionModeCard(c){if(!c)return '';return `<div class="card card-pad section-space"><h2>Execution capability boundaries</h2><p class="sub">Underlying agent: ${h(c.underlying_agent_modes.join(', '))}</p><p class="sub">Current adapter: ${h(c.adapter_supported_modes.join(', '))}</p><p class="sub">Available without a new live approval: ${h(c.currently_available_modes.join(', '))}</p><details><summary>Configuration and authorization restrictions</summary><pre>${pretty(c.blocked_modes)}</pre></details></div>`;}
function explorer(){const a=agent(),p=a.profile;return title('Agent explorer','Understand the contract. Keep assumptions visible.',btn('Refresh discovery','discover','',a.id))+executionModeCard(state.executionCapabilities)+(!p?`<div class="card">${empty('Discover this agent first')}</div>`:`<div class="grid stats">${[['Framework',p.framework],['Tools',p.tools.length],['Operations',p.capabilities.length],['Conversation',p.conversation?'Supported':'Not declared']].map(([l,v])=>`<div class="card card-pad"><div class="stat-label">${l}</div><strong>${h(v)}</strong></div>`).join('')}</div><div class="note">${h(p.unknowns.join(' · ')||'No additional unknowns declared. Runtime behavior still needs evidence.')}</div><div class="card"><div class="card-head"><h2>Capability inventory</h2>${btn('Enrich profile','edit-profile','tiny')}</div>${p.capabilities.map(c=>`<details><summary>${h(c.name)} <span class="sub">/ ${h(c.tool)}</span> ${badge(c.risk)} ${badge(c.provenance)}</summary><p class="sub">${h(c.description)}</p><p class="sub">Authorization: ${h(c.authorization)}</p><pre>${pretty(c.schema)}</pre><p class="tiny muted">${h(c.evidence.join(' · '))}</p></details>`).join('')}</div><div class="card card-pad section-space"><h2>Capability fingerprint</h2><pre>${h(p.fingerprint)}</pre>${btn('View full profile','view-profile','tiny')}</div>`);}
function draftStatus(s){const j=state.generationJobs.find(j=>j.suite_id===s.id);return j?`<div class="note"><strong>Verified draft request: ${h(j.status)}</strong><p>Requested ${j.requested_count} · Saved ${j.saved_count} · Remaining ${j.remaining_count}</p><p>${h(j.source)}</p><details><summary>Batch counts and validation findings</summary><pre>${pretty(j)}</pre></details></div>`:'';}
function suitePage(){const s=suite();return title('Test suite builder','Generate intentionally. Review expectations before execution.',btn('Edit suite JSON','edit-suite'))+`<div class="card card-pad"><form id="generate" class="toolbar"><div class="field"><label>Cases requested</label><input name="count" type="number" value="30" min="1" max="1000"></div><div class="field"><label>Focus</label><select name="focus"><option value="">Balanced coverage</option>${['argument_extraction','authorization','context_retention','confirmation','tool_routing','error_handling','regression'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Generator</label><select name="ai"><option value="false">Contract templates · offline</option><option value="true">AI · configured model</option></select></div><div class="field"><label>Generation budget ($)</label><input name="budget" type="number" value="0" min="0" step="0.25"></div><button class="primary">Generate suite</button></form></div><div class="toolbar section-space"><div class="field"><label>Saved suite</label><select id="suite-select">${options(suites(),s?.id)}</select></div>${btn('Quality review','suite-quality')}${btn('Recommend subset','recommend')}${btn('Historical evidence','historical-evidence')}${btn('Review all cases','review-all')}${btn('Open execution →','go-execution','primary')}</div>${s?`${draftStatus(s)}<div class="sub">${h(s.generation)} · ${s.cases.filter(c=>c.reviewed).length}/${s.cases.length} reviewed</div><div class="card section-space">${s.cases.map(c=>`<div class="case-card"><div class="case-top"><div class="grow"><div class="case-name">${h(c.name)}</div><p class="sub">${h(c.objective)}</p><div class="case-meta">${badge(c.category)}${badge(c.risk)}${badge(c.reviewed?'reviewed':'needs review')}<span class="tiny muted">P${c.priority} · ${c.turns.length} turn(s)</span></div></div>${btn('Review / edit','edit-case','tiny',c.id)}</div></div>`).join('')}</div>`:`<div class="card section-space">${empty('No suite for this agent','Generate cases from discovered capabilities.')}</div>`}`;}
function execution(){const s=suite(),p=state.plan;const modes=[['generate_only','A · Generate only'],['static','B · Static validation'],['historical','C · Historical traces'],['mock','D · Controlled mock'],['live','E · Live agent'],['multi_turn','F · Multi-turn workflow']];return title('Execution center','A plan is a proposal. Only your explicit approval authorizes live execution.')+`<div class="grid two-col"><div class="card card-pad"><h2>1. Select your scope</h2><div class="field section-space"><label>Test suite</label><select id="suite-select">${options(suites(),s?.id)}</select></div><div class="actions">${btn('Select all','select-all','tiny')}${btn('Clear','select-none','tiny')}<span class="sub">${state.selected.size} selected</span></div><div class="section-space" id="selection-list">${s?s.cases.map(c=>`<label class="checkbox-label"><input type="checkbox" data-test="${h(c.id)}" ${state.selected.has(c.id)?'checked':''}><span>${h(c.name)} ${badge(c.risk)} ${!c.reviewed?badge('unreviewed'):''}</span></label>`).join(''):empty('Create a suite first')}</div></div><div><div class="card card-pad"><h2>2. Configure execution</h2><form id="plan-form" class="section-space"><div class="field"><label>Mode</label><select name="mode">${modes.map(([v,l])=>`<option value="${v}" ${state.executionCapabilities?.supported_modes.includes(v)?'':'disabled'} ${v===(p?.mode||(state.executionCapabilities?.supported_modes.includes('mock')?'mock':state.executionCapabilities?.supported_modes[0]))?'selected':''}>${l}</option>`).join('')}</select></div><div class="mini-grid"><div class="field"><label>Reservation ceiling ($)</label><input name="budget" type="number" min="0" step="0.25" value="${p?.budget||0}"></div><div class="field"><label>Concurrency</label><input name="concurrency" type="number" min="1" max="8" value="${p?.concurrency||1}"></div><div class="field"><label>Timeout per call (s)</label><input name="timeout" type="number" min="1" max="300" value="${p?.timeout||30}"></div><div class="field"><label>Rate (requests / s)</label><input name="rate_per_second" type="number" min="0.1" max="20" step="0.1" value="${p?.rate_per_second||2}"></div><div class="field"><label>Judge budget ($)</label><input name="evaluation_budget" type="number" min="0" step="0.25" value="${p?.evaluation_budget||0}"></div></div><label class="checkbox-label"><input type="checkbox" name="judge"> Enable configured LLM Judge</label><div class="note">All selected live cases must be reviewed. Potential writes require verified isolation and additional explicit authorization.</div><button class="primary wide">Preview exact plan</button></form></div></div></div>${p?planPreview(p):''}<div class="card section-space"><div class="card-head"><h2>Run progress</h2>${btn('Refresh','refresh','tiny')}</div>${runTable(runs().slice(0,8))}</div>`;}
function planPreview(p){return `<div class="card section-space"><div class="card-head"><h2>3. Review & authorize exact plan</h2>${badge(p.mode)}</div><div class="card-pad"><div class="kpi-row"><div><strong>${p.test_ids.length}</strong><span class="sub">Selected cases</span></div><div><strong>${p.max_calls}</strong><span class="sub">Maximum target calls</span></div><div><strong>$${p.estimated_cost.toFixed(2)}</strong><span class="sub">Estimated reservation</span></div><div><strong>$${p.budget.toFixed(2)}</strong><span class="sub">Reservation ceiling</span></div></div>${p.agent_snapshot.config?.model_budget?`<p><strong>Real HR model:</strong> ${h(p.agent_snapshot.config.model_budget.model)} · maximum ${p.agent_snapshot.config.model_budget.max_calls} calls · $${p.agent_snapshot.config.model_budget.max_estimated_cost_usd.toFixed(2)} model gateway ceiling. The $${p.budget.toFixed(2)} reservation is not a measured bill. Tracing disabled; synthetic read-only database.</p>`:''}<p><strong>${h(p.agent_snapshot.name)}</strong> · ${h(p.environment)} · ${badge(p.risk)}</p><p class="sub">${h(p.side_effects.join(' · '))}</p><details><summary>Exact immutable plan, target configuration and test snapshots</summary><pre>${pretty(p)}</pre></details><p class="tiny muted">Plan digest: ${h(p.digest)}</p><label class="checkbox-label section-space"><input type="checkbox" id="approval-checkbox"> I approve this exact plan, target, test selection, mode, risks and budgets.</label><label class="checkbox-label"><input type="checkbox" id="additional-checkbox"> I additionally authorize potential business side effects in the verified isolated environment.</label><div class="actions section-space">${btn('Approve exact plan','approve-plan','primary',p.id)}${btn(p.mode==='live'||p.mode==='multi_turn'?'Execute approved plan':'Execute offline plan','run-plan','',p.id)}</div><p class="sub" id="approval-status">${['live','multi_turn'].includes(p.mode)?'Live execution requires backend approval.':'Offline evaluation does not invoke the target; no live approval required.'}</p></div></div>`;}
function results(){const r=run();return title('Results explorer','Follow the evidence from input to tool call to final response.',btn('Refresh results','refresh'))+`<div class="toolbar"><div class="field"><label>Run</label><select id="run-select">${options(runs().map(r=>({...r,name:r.id.slice(0,8)+' · '+r.mode+' · '+r.status})),r?.id)}</select></div>${r?btn('Cancel run','cancel-run','danger',r.id):''}${r?btn('Failure analysis','failures','',r.id):''}</div>${r?`<div class="grid stats">${['PASS','FAIL','INCONCLUSIVE','ERROR'].map(v=>`<div class="card stat"><div class="stat-label">${badge(v)}</div><div class="stat-number">${r.results.filter(x=>x.verdict===v).length}</div></div>`).join('')}</div><div class="card card-pad"><div class="split"><h2>${h(r.mode)} evaluation</h2>${badge(r.status)}</div><p class="sub">${r.calls} target calls · $${r.reserved_cost.toFixed(3)} reserved · measured cost ${r.measured_cost===null?'unavailable':'$'+r.measured_cost.toFixed(4)}</p><div class="progress-bar"><i data-width="${r.results.length/Math.max(1,state.plans.find(p=>p.id===r.plan_id)?.test_ids.length||1)*100}"></i></div></div><div class="card section-space">${r.results.map(x=>{const c=state.plans.find(p=>p.id===r.plan_id)?.snapshots.find(c=>c.id===x.test_case_id);return `<details><summary>${badge(x.verdict)} ${h(c?.name||x.test_case_id)} <span class="sub">· ${h(x.evidence.source)}</span></summary><p class="sub">${h(c?.objective||'')}</p><h3>Final response</h3><p class="result-final">${h(x.evidence.final??'No final-response observation')}</p><h3>Deterministic assertions</h3>${x.findings.map(f=>`<p class="sub">${badge(f.verdict)} ${h(f.criterion)} — ${h(f.explanation)}</p>`).join('')}<h3>Observed tool calls</h3><pre>${pretty(x.evidence.tool_calls)}</pre><h3>Judge findings</h3><pre>${pretty(x.judge_findings)}</pre><div class="actions">${btn('Full evidence','view-evidence','tiny',x.id)}${btn('Manual override','override-result','tiny',x.id)}</div></details>`}).join('')}</div>`:`<div class="card">${empty('No results to inspect')}</div>`}`;}
async function coveragePage(){const c=await api('/agents/'+agent().id+'/coverage');$('#view').innerHTML=title('Coverage that means something','Generated, reviewed, executed and passed coverage remain separate.')+`<div class="grid stats">${[['Known operations',c.total_operations],['Generated coverage',c.generated_operations+'/'+c.total_operations],['Live executed operations',c.inventory.filter(r=>r.executed>0).length],['Live passed operations',c.inventory.filter(r=>r.passed>0).length]].map(([l,v])=>`<div class="card stat"><div class="stat-label">${l}</div><div class="stat-number">${v}</div></div>`).join('')}</div><div class="card"><div class="card-head"><h2>Operation coverage matrix</h2>${btn('Generate missing coverage','go-suites','tiny')}</div><div class="table-scroll"><table><thead><tr><th>Operation / tool</th><th>Risk</th><th>Generated</th><th>Reviewed</th><th>Live run</th><th>Live passed</th><th>Offline evaluated</th></tr></thead><tbody>${c.inventory.map(r=>`<tr><td><strong>${h(r.operation)}</strong><div class="tiny muted">${h(r.tool)}</div><div class="tiny muted">${h(r.categories.join(', '))}</div></td><td>${badge(r.risk)}</td><td>${r.generated}</td><td>${r.reviewed}</td><td>${r.executed}</td><td>${r.passed}</td><td>${r.offline_evaluated}</td></tr>`).join('')}</tbody></table></div></div>`;}
function regressionPage(){const rr=runs().map(r=>({...r,name:r.id.slice(0,8)+' · '+r.mode}));return title('Regression comparison','Compare the same cases across saved runs. Original evidence stays immutable.')+`<div class="card card-pad"><form id="compare" class="toolbar"><div class="field"><label>Baseline</label><select name="before">${options(rr,rr[1]?.id)}</select></div><div class="field"><label>Candidate</label><select name="after">${options(rr,rr[0]?.id)}</select></div><button class="primary">Compare runs</button></form><div id="comparison">${empty('Choose two runs','Matching test IDs establish comparable cases.')}</div></div>`;}
function reportsPage(){const r=run();return title('Reports & evaluation health','Export reproducible evidence. Track the judge and audit the decisions.')+`<div class="card card-pad"><div class="toolbar"><div class="field"><label>Report run</label><select id="run-select">${options(runs().map(r=>({...r,name:r.id.slice(0,8)+' · '+r.mode})),r?.id)}</select></div>${['json','md','html'].map(f=>btn('Download '+f.toUpperCase(),'download-'+f,'',r?.id||'')).join('')}${btn('Preview report','preview-report','primary',r?.id||'')}</div><p class="sub">Includes target, snapshots, approval, results, evidence, latency, reported usage, reservations and failure hypotheses.</p></div><div class="grid mini-grid section-space"><div class="card card-pad"><h2>Judge calibration</h2><p class="sub">Illustrative golden labels require human review. Agreement is not claimed until predictions and reference labels exist.</p><div class="actions">${btn('View calibration','calibration')}${btn('Review golden examples','golden')}</div></div><div class="card card-pad"><h2>Cost & audit trail</h2><p class="sub">Inspect generation, Copilot, target and evaluation reservations separately from measured provider usage.</p><div class="actions">${btn('Usage ledger','usage')}${btn('Audit log','audit')}${btn('Manual overrides','overrides')}</div></div></div><div class="card card-pad section-space"><h2>Explicit LangSmith exports</h2><p class="sub">These controls write only to your configured LangSmith account when you request them.</p><div class="actions">${btn('Create dataset from selected suite','smith-dataset')}${btn('Record run metadata','smith-experiment','',r?.id||'')}${btn('Attach trace feedback','smith-feedback')}</div></div><div id="report-output" class="section-space"></div>`;}
async function chatPage(){let chats=await api('/chats');let current=state.forceNewChat?null:chats.find(c=>c.id===state.chatSession)||chats.find(c=>c.agent_id===agent().id);if(current){state.chatSession=current.id;state.chatMessages=current.messages;}else{state.chatSession=null;state.chatMessages=[];}$('#view').innerHTML=title('Your QA Copilot','One conversation. Real platform tools. Approval stays with you.',btn('New conversation','new-chat'))+`<div class="grid two-col"><div class="card chat-shell"><div class="card-head"><h2>✧ AgentQA Copilot</h2>${badge(state.providerPlanId?'model scope selected; backend checks approval':'offline command mode')}</div><div class="chat-messages" id="chat-messages">${state.chatMessages.length?state.chatMessages.map(chatBubble).join(''):`<div class="empty"><strong>What would you like to investigate?</strong>Start with your agent’s capabilities or design a focused test suite.<div class="actions section-space">${['Explain what tools it has','Generate 30 test cases','Show uncovered operations'].map(t=>btn(h(t),'chat-prompt','prompt-chip',t)).join('')}</div></div>`}</div><form id="chat-form" class="chat-input"><input name="message" aria-label="Message Copilot" placeholder="Ask about capabilities, tests, failures…" required><button class="primary">Send ↑</button></form></div><div><div class="card card-pad"><div class="eyebrow">Selected context</div><h2>${h(agent().name)}</h2><p class="sub">${agent().profile?.tools.length||0} tools · ${agent().profile?.capabilities.length||0} operations</p><div class="note">The Copilot can inspect, generate and explain. It has no approval or execution tool.</div><label class="field"><span class="sub">Copilot request budget ($)</span><input id="chat-budget" type="number" value="1" min="0" step="0.25"></label></div><div class="card card-pad section-space"><h3>Working artifacts</h3><p class="sub">Model tool calls and results are recorded separately from target execution.</p>${btn('Inspect Copilot tool evidence','copilot-events','tiny')}<p class="sub">Generated suites appear in Suite Builder. Saved run evidence is available in Results Explorer.</p>${btn('View test suites →','go-suites','tiny')}</div></div></div>`;$('#chat-messages').scrollTop=999999;}
function chatBubble(m){return `<div class="chat-message ${h(m.role)}"><div class="chat-role">${m.role==='user'?'You':'✧ Copilot'}</div><div class="chat-bubble">${h(m.content)}</div></div>`;}
async function providerPage(){const data=await api('/provider/plans');const p=data.plans.find(x=>x.id===state.providerPlanId)||data.plans.find(x=>x.agent_id===agent().id);if(p)state.providerPlanId=p.id;state.providerPlan=p;const approved=data.approvals.find(a=>a.id===p?.id);$('#view').innerHTML=title('AI activation & approval','Provider spending and LangSmith access require separate exact approval.')+`<div class="card card-pad"><h2>Contract-grounded compiler demonstration</h2><div class="actions">${btn('Compile 3 scenario intents','compiler-3')}${btn('Compile 40 scenario intents','compiler-40')}${btn('Compile partial batch','compiler-partial')}</div><h2>Legacy offline contract demonstration</h2><p class="sub">Controlled model fixtures use the actual graph, tools and persistence. No provider, target or LangSmith calls. Historical legacy workflow fixtures; the captured rejected payload is covered separately by compiler regression tests.</p><div class="actions">${btn('Offline: save 3 drafts','offline-3')}${btn('Offline: save 40 drafts','offline-40')}${btn('Offline: malformed count','offline-malformed')}${btn('Offline: partial batch','offline-partial')}${btn('Verify judge parser locally','offline-judge')}</div><div id="offline-result"></div></div><div class="card card-pad section-space"><h2>Private server configuration</h2><p class="sub">Enter credentials only in the project’s ignored .env file. Restart the backend after editing. No credential form sends keys to the browser.</p><pre>${pretty(state.status.provider)}</pre></div><div class="card card-pad section-space"><h2>Bounded AI acceptance</h2><label>Saved exact plan<select id="provider-plan-select">${data.plans.filter(x=>x.agent_id===agent().id).map(x=>`<option value="${h(x.id)}" ${x.id===p?.id?'selected':''}>${h(x.acceptance_flow||x.kind||'initial')} · ${h(x.id)}</option>`).join('')}</select></label><p class="sub">${p?.acceptance_flow==='judge'?'Independent Judge: one recorded evaluation, at most one model call.':p?.acceptance_flow==='generation'?'Generation: one Copilot request for 3 cases (at most four calls), one direct request for 3 cases (one call).':p?.kind==='minimal'?'Minimal: one 3-case Copilot interaction (at most four calls), one direct 3-case generation call, one judge call.':p?.retry_of?'Recovery: no repeated connectivity check. One Copilot interaction (up to six model calls), three AI drafts, three recorded judge evaluations.':'One connectivity check; one exact Copilot prompt (up to six model calls); three AI draft cases; three recorded judge examples.'} No target calls. No LangSmith export.</p><label class="checkbox-label"><input id="request-tracing" type="checkbox"> Also propose LangSmith tracing (separate remote approval required).</label>${btn('Prepare generation acceptance','prepare-minimal-generation','primary')}${btn('Prepare independent Judge acceptance','prepare-minimal-judge')}${approved?.stopped&&!p?.retry_of?btn('Prepare corrected recovery scope','prepare-recovery'):''}${p?`<p>Plan ${h(p.id)} · ${p.max_calls} maximum model calls · $${p.maximum_estimated_cost_usd.toFixed(5)} conservative reservation · $${p.budget_usd.toFixed(5)} ceiling</p><details><summary>Review exact models, data disclosure, prompt, examples and digest</summary><pre>${pretty(p)}</pre></details>${btn('Download exact plan JSON','provider-export')}<label class="checkbox-label"><input id="provider-consent" type="checkbox"> I approve this exact provider plan and its budget.</label><div class="actions">${btn('Approve exact paid scope','approve-provider','primary')}${approved&&!approved.stopped?btn('Stop approved batch','stop-provider','danger'):''}${p.operations.some(o=>o.name==='connectivity')?btn('Run approved connectivity check','provider-check'):''}${p.operations.some(o=>o.name==='copilot')?btn('Load exact Copilot prompt','provider-prompt'):''}${p.operations.some(o=>o.name==='generation')?btn('Generate approved 3 AI drafts','provider-generate'):''}${p.golden_ids.length?btn(p.golden_ids.length===1?'Judge approved recorded example':'Judge approved recorded examples','provider-judge'):''}${p.remote_trace_plan_id?btn('Review linked tracing request','review-linked-trace'):''}</div><p class="sub">${approved?.stopped?`STOPPED: ${h(approved.stop_reason||'Provider request failed')}. Fresh approval required for any retry.`:approved?'Backend approval recorded; counters shown below.':'Not approved. Preparing or selecting this plan makes no provider request.'}</p><pre>${pretty(approved||{})}</pre>`:''}</div><div class="card card-pad section-space"><h2>Isolated HR live acceptance preparation</h2><p class="sub">Prepare a review artifact only. Starting or calling HR requires verified isolation and fresh execution approval.</p>${btn('Prepare isolated HR live plan','hr-prepare-live')}${btn('Review saved HR preparation','hr-review-preparation')}<h2>LangSmith remote access</h2><p class="sub">Prepare a read-only project-list request; review and explicitly approve before sending. Imported historical links do not verify connectivity.</p><div class="actions">${btn('Prepare project-list request','remote-prepare')}${btn('Review pending remote request','remote-review')}${btn('Approve reviewed remote request','remote-approve')}${btn('List projects with approval','remote-list')}${btn('Review saved project response','remote-project-results')}${btn('Analyze imported historical trace locally','remote-local-analysis')}${btn('Prepare selected HR trace-read plan','remote-prepare-trace')}${btn('Retrieve approved historical HR trace','remote-read-trace')}</div></div>`;}
async function sendChat(message){const budget=Number($('#chat-budget')?.value||1);$('#chat-messages').insertAdjacentHTML('beforeend',chatBubble({role:'user',content:message}));toast('Working with platform tools…');const data=await api('/chat','POST',{agent_id:agent().id,session_id:state.chatSession,message,budget,provider_plan_id:state.providerPlanId||null});state.chatSession=data.session_id;state.forceNewChat=false;await refresh();await render();}
function bindForms(){
 $$('.field').forEach((e,i)=>{const input=e.querySelector('input,select,textarea'),label=e.querySelector('label');if(input&&label){input.id=input.id||'field-'+state.page+'-'+i;label.htmlFor=input.id;}});
 $$('[data-height]').forEach(e=>e.style.height=e.dataset.height+'%');
 $$('[data-width]').forEach(e=>e.style.width=e.dataset.width+'%');
 const bind=(id,fn)=>{const el=$(id);if(el)el.onsubmit=async e=>{e.preventDefault();const button=el.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{await fn(new FormData(el))}catch(err){toast(err.message)}finally{if(button)button.disabled=false}}};
 bind('#generate',async f=>{const s=await api('/agents/'+agent().id+'/generate','POST',{provider_plan_id:state.providerPlanId||null,count:Number(f.get('count')),focus:f.get('focus'),ai:f.get('ai')==='true',budget:Number(f.get('budget'))});state.suiteId=s.id;await refresh();await render();toast(`Saved ${s.cases.length} cases. Review before execution.`)});
 bind('#plan-form',async f=>{if(!suite())throw Error('Select a suite');state.plan=await api('/plans','POST',{agent_id:agent().id,suite_id:suite().id,test_ids:[...state.selected],mode:f.get('mode'),budget:Number(f.get('budget')),concurrency:Number(f.get('concurrency')),timeout:Number(f.get('timeout')),rate_per_second:Number(f.get('rate_per_second')),judge:f.get('judge')==='on',evaluation_budget:Number(f.get('evaluation_budget'))});await refresh();await render();$('#approval-checkbox')?.scrollIntoView({behavior:'smooth',block:'center'});toast('Plan saved. Review exact snapshots before approval.')});
 bind('#chat-form',async f=>sendChat(f.get('message')));
 bind('#compare',async f=>{const c=await api('/compare?before='+encodeURIComponent(f.get('before'))+'&after='+encodeURIComponent(f.get('after')));$('#comparison').innerHTML=`<h3>${c.regressions} regressions ${c.comparable_modes?'':'· different execution modes'}</h3><table><thead><tr><th>Case ID</th><th>Baseline</th><th>Candidate</th><th>Latency delta</th></tr></thead><tbody>${c.changes.map(x=>`<tr><td>${h(x.test_case_id.slice(0,12))}</td><td>${badge(x.before||'missing')}</td><td>${badge(x.after||'missing')}</td><td>${x.latency_delta_ms===null?'—':x.latency_delta_ms.toFixed(2)+' ms'}</td></tr>`).join('')}</tbody></table>`});
 bind('#trace-import',async f=>{$('#smith-output').textContent=JSON.stringify(await api('/langsmith/import','POST',{project:f.get('project'),limit:Number(f.get('limit'))}),null,2)});
}
async function navigate(page){state.page=page;location.hash=page;await render();}
function modalData(name,data){$('#editor-content').innerHTML=`<h2>${h(name)}</h2><pre>${pretty(data)}</pre>`;$('#editor').showModal();}
function addAgent(){const template={name:'My REST agent',adapter:'rest',endpoint:'http://127.0.0.1:8124',environment:'isolated',config:{discovery_path:'/capabilities',invoke_path:'/chat',message_field:'message',response_path:'response',session_field:'session_id',tool_calls_path:'tool_calls'},auth_env:null};jsonEditor('Connect an agent',template,async data=>{const a=await api('/agents','POST',data);state.agentId=a.id;await refresh();await render()})}
async function action(name,id){
 if(name.startsWith('go-'))return navigate(name.slice(3));
 if(name.startsWith('compiler-')){const data=await api('/offline/compiler','POST',{agent_id:agent().id,count:name==='compiler-40'?40:3,scenario:name==='compiler-partial'?'partial':'success'});state.suiteId=data.compilation.suite_id;await refresh();await navigate('suites');return modalData('Controlled scenario compiler counts',data)}
 if(name==='offline-judge')return modalData('Local judge schema and grounding fixture',await api('/offline/judge-contract'));
 if(name.startsWith('offline-')){const scenario=name==='offline-malformed'?'malformed':name==='offline-partial'?'partial':'success';const data=await api('/offline/drafts','POST',{agent_id:agent().id,count:name==='offline-40'?40:3,scenario});state.offlineResult=data;await refresh();const job=data.result.draft_requests[0];if(job){state.suiteId=job.suite_id;await navigate('suites')}return modalData('Controlled offline workflow · not live AI',data)}
 if(name.startsWith('prepare-minimal')){const p=await api('/provider/plans','POST',{agent_id:agent().id,kind:name==='prepare-minimal-judge'?'minimal_judge':name==='prepare-minimal-generation'?'minimal_generation':'minimal'});state.providerPlanId=p.id;return render()}
 if(name==='prepare-provider'){const p=await api('/provider/plans','POST',{agent_id:agent().id,trace:$('#request-tracing')?.checked||false});state.providerPlanId=p.id;return render()}
 if(name==='prepare-recovery'){const p=await api('/provider/plans','POST',{agent_id:agent().id,retry_of:state.providerPlanId});state.providerPlanId=p.id;return render()}
 if(name==='provider-export'){const response=await fetch('/api/provider/plans/'+state.providerPlanId+'/export',{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw Error('Exact plan export blocked');const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='provider-plan-'+state.providerPlanId+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);return}
 if(name==='approve-provider'){if(!$('#provider-consent')?.checked)throw Error('Review the exact paid scope and check its approval statement');await api('/provider/plans/'+state.providerPlanId+'/approve','POST',{digest:state.providerPlan.digest,confirmation:'I approve this exact provider plan'});return render()}
 if(name==='stop-provider'){await api('/provider/plans/'+state.providerPlanId+'/stop','POST');return render()}
 if(name==='provider-check')return modalData('Actual provider connectivity result',await api('/provider/plans/'+state.providerPlanId+'/connectivity','POST'));
 if(name==='provider-prompt'){state.chatSession=null;state.forceNewChat=true;await navigate('chat');$('#chat-form input[name=message]').value=state.providerPlan.prompt;return}
 if(name==='provider-generate'){const p=state.providerPlan;const suite=await api('/agents/'+agent().id+'/generate','POST',{ai:true,budget:1,count:p.generation.count,focus:p.generation.focus,provider_plan_id:p.id});state.suiteId=suite.id;await refresh();return navigate('suites')}
 if(name==='provider-judge'){const out=[];for(const id of state.providerPlan.golden_ids)out.push(await api('/golden/'+id+'/judge','POST',{budget:1,provider_plan_id:state.providerPlanId}));return modalData('Actual judge findings',out)}
 if(name==='copilot-events')return modalData('Recorded Copilot platform tool evidence',await api('/copilot/evidence'));
 if(name==='hr-prepare-live'||name==='hr-review-preparation'){
 const p=name==='hr-prepare-live'?await api('/hr-live/preparations','POST'):(await api('/hr-live/preparations'))[0];if(!p)throw Error('No saved preparation');state.hrPreparation=p;
 $('#editor-content').innerHTML=`<h2>Isolated HR live acceptance — BLOCKED</h2><p>Plan ${h(p.id)} · ${badge('BLOCKED')} · not executable · no target calls</p><p>Proposed endpoint ${h(p.target_identity.runtime_endpoint)} · LangGraph · ${p.tests.length} tests / ${p.limits.proposed_inference_target_calls} turns</p><p>Digest ${h(p.digest)}<br>Expires ${h(p.expires_at)}</p><h3>Isolation and approval blockers</h3><ul>${p.blockers.map(b=>`<li><strong>${h(b.id)}</strong>: ${h(b.detail)}</li>`).join('')}</ul><h3>Selected synthetic tests</h3>${p.tests.map(t=>`<p><strong>${h(t.id)} — ${h(t.name)}</strong><br>${t.inputs.map(h).join('<br>')}</p>`).join('')}<p><button disabled>Approve live execution — BLOCKED</button></p>${btn('Download exact blocked HR plan JSON','hr-export-preparation')}<details><summary>Full immutable proposed plan, data disclosure and limits</summary><pre>${pretty(p)}</pre></details>`;$('#editor').showModal();return;
 }
 if(name==='hr-export-preparation'){const p=state.hrPreparation;if(!p)throw Error('Prepare a plan first');const response=await fetch('/api/hr-live/preparations/'+p.id+'/export',{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw Error('Immutable export validation failed');const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='HR_LIVE_ACCEPTANCE_PLAN_EXACT.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);return}
 if(name==='remote-local-analysis'){
 const r=await api('/langsmith/trace-analysis');state.traceAnalysis=r;
 $('#editor-content').innerHTML=`<h2>Historical trace QA analysis</h2><p>${badge('historical')} Imported evidence · no new execution · redacted</p><p>Trace ${h(r.trace_id)}</p><p>${r.span_count} spans · ${r.child_span_count} descendants · ${r.tool_call_count} tool calls · ${r.feedback_count} existing feedback records</p><p>Historical operation coverage: ${r.coverage.observed_historical_operations}/${r.coverage.discovered_operations}. New live executions: 0. Historical model spans: ${r.span_types.llm||0}; new model calls: 0.</p><p>Import integration ${badge(r.integration_status)} · Historical behavior ${badge(r.qa_verdict)}</p>${btn('Download redacted QA JSON','export-trace-analysis','primary')}<h3>Observed tool calls — redacted</h3><table><thead><tr><th>Operation</th><th>Arguments</th><th>Backend result</th></tr></thead><tbody>${r.tool_calls.map(c=>`<tr><td>${h(c.operation)}<br><small>${h(c.span_id)}</small></td><td><pre>${pretty(c.arguments)}</pre></td><td>${h(c.result?.code||(c.result?.ok===true?'ok=true; HR values withheld':'unknown'))}</td></tr>`).join('')}</tbody></table><h3>Local deterministic findings — no paid Judge</h3><table><thead><tr><th>Check</th><th>Verdict</th><th>Evidence / limitation</th></tr></thead><tbody>${r.findings.map(f=>`<tr><td>${h(f.criterion)}</td><td>${badge(f.verdict)}</td><td>${h(f.explanation)}</td></tr>`).join('')}</tbody></table><details><summary>Source provenance, timestamps, redacted results and coverage inventory</summary><pre>${pretty(r)}</pre></details>`;
 $('#editor').showModal();return;
 }
 if(name==='export-trace-analysis'){if(!state.traceAnalysis)throw Error('Analyze imported evidence first');const blob=new Blob([JSON.stringify(state.traceAnalysis,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='TRACE_BACKED_QA_ANALYSIS.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);return}

 if(name==='remote-project-results')return modalData('Saved real LangSmith project responses',await api('/langsmith/project-listings'));
 if(name==='remote-prepare-trace'){state.remotePlan=await api('/langsmith/prepare-hr-trace-read','POST');return modalData('Review selected historical HR trace-read plan — NOT approved',state.remotePlan)}
 if(name==='remote-read-trace'){if(state.remotePlan?.action!=='trace_read')throw Error('Prepare and explicitly approve the exact trace-read plan first');return modalData('Actual historical trace import',await api('/langsmith/trace-read/'+state.remotePlan.id,'POST'))}
 if(name==='remote-prepare'){state.remotePlan=await api('/langsmith/plans','POST',{action:'projects',payload:{}});return modalData('Review exact remote request; approval is a separate action',state.remotePlan)}
 if(name==='review-linked-trace'){state.remotePlan=await api('/langsmith/plans/'+state.providerPlan.remote_trace_plan_id);return modalData('Review linked tracing request; approve separately below',state.remotePlan)}
 if(name==='remote-review')return modalData('Pending remote request',state.remotePlan||{status:'Prepare a request first'});
 if(name==='remote-approve'){if(!state.remotePlan)throw Error('Prepare and review a request first');return jsonEditor('Explicit remote approval',{digest:state.remotePlan.digest,confirmation:''},async data=>modalData('Remote approval',await api('/langsmith/plans/'+state.remotePlan.id+'/approve','POST',data)))}
 if(name==='remote-list'){if(!state.remotePlan)throw Error('Prepare and approve a request first');return modalData('Actual LangSmith projects',await api('/langsmith/projects?remote_plan_id='+state.remotePlan.id))}
 if(name==='logout'){sessionStorage.removeItem('agentqa-token');state.token='';return login()}
 if(name==='refresh'){await refresh();return render()}
 if(name==='add-agent')return addAgent();
 if(name==='discover'){toast('Reading metadata only…');await api('/agents/'+id+'/discover','POST');await refresh();await render();return toast('Metadata discovered. Runtime behavior remains unverified.')}
 if(name==='verify-isolation'){await api('/agents/'+id+'/verify-isolation','POST');await refresh();await render();return toast('Metadata matches the operator-configured isolated deployment.')}
 if(name==='select-explore'){state.agentId=id;localStorage.setItem('agentqa-agent',id);return navigate('explorer')}
 if(name==='historical-evidence')return modalData('Imported historical evidence IDs · copy into a case historical_evidence_id',await api('/evidence'));
 if(name==='view-profile')return modalData('Agent profile',agent().profile);
 if(name==='edit-profile')return jsonEditor('Enrich profile',agent().profile,async data=>{await api('/agents/'+agent().id+'/profile','PUT',data);await refresh();await render()});
 if(name==='edit-suite'){if(!suite())throw Error('Generate a suite first');return jsonEditor('Edit suite',suite(),async data=>{await api('/suites/'+suite().id,'PUT',data);await refresh();await render()})}
 if(name==='edit-case'){const s=suite(),c=s.cases.find(c=>c.id===id);return jsonEditor('Review test case · set reviewed to true',c,async data=>{const updated={...s,cases:s.cases.map(c=>c.id===id?data:c)};await api('/suites/'+s.id,'PUT',updated);await refresh();await render()})}
 if(name==='review-all'){const s=suite();if(!s)throw Error('No suite');jsonEditor('Review exact suite before marking all reviewed',{...s,cases:s.cases.map(c=>({...c,reviewed:true,review_notes:c.review_notes+' | Reviewed in authenticated UI'}))},async data=>{await api('/suites/'+s.id,'PUT',data);await refresh();await render();toast('Case review saved. Execution approval is separate.')});return}
 if(name==='suite-quality'){if(!suite())throw Error('No suite selected');return modalData('Automated contract and oracle quality review',await api('/suites/'+suite().id+'/quality'))}
 if(name==='recommend'){if(!suite())throw Error('No suite');return modalData('Cost-aware recommended subset',await api('/suites/'+suite().id+'/recommend?budget=5'))}
 if(name==='select-all'){state.selected=new Set((suite()?.cases||[]).map(c=>c.id));return render()}
 if(name==='select-none'){state.selected.clear();return render()}
 if(name==='approve-plan'){if(!$('#approval-checkbox')?.checked)throw Error('Review the exact plan and check the approval statement');await api('/plans/'+id+'/approve','POST',{digest:state.plan.digest,additional_authorization:$('#additional-checkbox').checked,confirmation:'I approve this exact plan'});$('#approval-status').textContent='Approved by authenticated local administrator. Approval expires after 30 minutes and is single-use.';return toast('Exact plan approved.')}
 if(name==='run-plan'){const r=await api('/plans/'+id+'/run','POST');state.runId=r.id;await refresh();await navigate('results');return toast('Run started. Evidence appears as each case completes.')}
 if(name==='inspect-run'){state.runId=id;return navigate('results')}
 if(name==='cancel-run'){await api('/runs/'+id+'/cancel','POST');await refresh();await render();return toast('Cancellation requested. Already completed target effects cannot be rolled back.')}
 if(name==='failures')return modalData('Failure clusters · hypotheses, not proven causes',await api('/runs/'+id+'/failures'));
 if(name==='view-evidence'){const result=run().results.find(r=>r.id===id);return modalData('Observed execution evidence',result.evidence)}
 if(name==='override-result'){return jsonEditor('Append an audited manual override',{result_id:id,verdict:'INCONCLUSIVE',reason:'Human reviewer: describe evidence and rationale'},async data=>{await api('/runs/'+run().id+'/override','POST',data);toast('Override recorded separately; original preserved.')})}
 if(name.startsWith('download-')){if(!id)throw Error('Select a run first');const format=name.slice(9);const response=await fetch('/api/reports/'+id+'?format='+format,{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw Error('Report download failed');const blob=await response.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='agentqa-'+id+'.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return}
 if(name==='preview-report'){if(!id)throw Error('Select a run first');return modalData('QA report preview',await api('/reports/'+id+'?format=json'))}
 if(name==='calibration')return modalData('Judge calibration',await api('/calibration'));
 if(name==='usage')return modalData('Cost & usage ledger',await api('/usage'));
 if(name==='audit')return modalData('Immutable audit entries',await api('/audit'));
 if(name==='overrides')return modalData('Audited manual overrides',await api('/overrides'));
 if(name==='golden'){const items=await api('/golden');$('#editor-content').innerHTML='<h2>Golden examples</h2><p class="sub">Seed labels are illustrative. Review evidence and labels explicitly.</p>'+items.map(g=>`<div class="agent-row"><div class="grow"><strong>${h(g.name)}</strong><div class="sub">${h(g.reference)} · ${g.reviewed_by?'human reviewed':'unreviewed'}</div></div>${btn('Review','edit-golden','tiny',g.id)}${btn('Run judge ($'+0.25+' reservation)','judge-golden','tiny',g.id)}</div>`).join('');$('#editor').showModal();return}
 if(name==='judge-golden')return jsonEditor('Request judge calibration on this example',{budget:0.25},async data=>{const out=await api('/golden/'+id+'/judge','POST',data);modalData('Judge calibration findings',out)});
 if(name==='edit-golden'){const item=(await api('/golden')).find(x=>x.id===id);return jsonEditor('Review golden reference',{reference:item.reference,judge_verdict:item.judge_verdict,notes:item.notes,evidence:item.evidence},async data=>{await api('/golden/'+id,'PUT',data);toast('Golden reference review recorded.')})}
 if(name==='new-chat'){state.chatSession=null;state.chatMessages=[];state.forceNewChat=true;$('#chat-messages').innerHTML=empty('New conversation','Your next message starts a new bounded session.');return}
 if(name==='chat-prompt')return sendChat(id);
 if(name==='save-json'){const data=JSON.parse($('#json-editor').value);$('#editor').close();await state.editorSave(data);return toast('Saved.')}
 if(name==='smith-projects'){$('#smith-output').textContent=JSON.stringify(await api('/langsmith/projects'),null,2);return}
 if(name==='smith-dataset'){if(!suite())throw Error('Choose a suite in Suite Builder first');return jsonEditor('Request LangSmith dataset creation',{name:'AgentQA '+suite().name,suite_id:suite().id},async data=>modalData('Dataset created',await api('/langsmith/dataset','POST',data)))}
 if(name==='smith-experiment'){if(!id)throw Error('Select a run');return jsonEditor('Record experiment metadata',{name:'AgentQA '+id.slice(0,8),run_id:id},async data=>{const out=await api('/langsmith/experiment','POST',data);toast('Created project '+out.id)})}
 if(name==='smith-feedback')return jsonEditor('Attach evaluation to a LangSmith trace',{trace_id:'',key:'agentqa_quality',score:0,comment:'Evidence-grounded review'},async data=>{await api('/langsmith/feedback','POST',data);toast('Feedback recorded')});
}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-page]');if(nav){try{await navigate(nav.dataset.page)}catch(err){toast(err.message)}return}const el=e.target.closest('[data-action]');if(!el)return;el.disabled=true;try{await action(el.dataset.action,el.dataset.id)}catch(err){toast(err.message)}finally{el.disabled=false}});
document.addEventListener('change',async e=>{try{if(e.target.id==='provider-plan-select'){state.providerPlanId=e.target.value;await render()}if(e.target.id==='global-agent'){state.agentId=e.target.value;state.providerPlanId=null;state.providerPlan=null;state.suiteId='';state.runId='';state.plan=null;state.selected.clear();state.chatSession=null;state.chatMessages=[];localStorage.setItem('agentqa-agent',state.agentId);await render()}if(e.target.id==='suite-select'){state.suiteId=e.target.value;state.selected.clear();state.plan=null;await render()}if(e.target.id==='run-select'){state.runId=e.target.value;await render()}if(e.target.dataset.test){if(e.target.checked)state.selected.add(e.target.dataset.test);else state.selected.delete(e.target.dataset.test)}}catch(err){toast(err.message)}});
function startPolling(){clearInterval(poll);poll=setInterval(async()=>{try{if(state.runs.some(r=>r.status==='running'||r.status==='queued')){await refresh();if(['results','dashboard'].includes(state.page)&&!$('#editor').open)await render()}}catch(err){toast(err.message)}},2000)}
(async()=>{if(!state.token)return login();try{await refresh();await render();startPolling()}catch(err){login();toast(err.message)}})();
